import random
import time

class FacilityAccess:
    def __init__(self, facility_name):
        self.facility_name = facility_name
        self.permissions = {
            "admin": ["access_all_areas", "use_all_equipment"],
            "staff": ["access_research_areas", "use_common_equipment"],
            "guest": ["access_common_areas", "use_common_equipment"]
        }
        self.current_user = None

    def login(self, user_type):
        if user_type not in self.permissions:
            print(f"Invalid user type: {user_type}")
            return False
        self.current_user = user_type
        print(f"User {user_type} has logged in to {self.facility_name}.")
        return True

    def check_permissions(self):
        if self.current_user is None:
            print("No user is currently logged in.")
            return False
        print(f"User {self.current_user} has the following permissions in {self.facility_name}:")
        for permission, actions in self.permissions[self.current_user].items():
            print(f"  - {permission}: {', '.join(actions)}")

    def perform_task(self, task):
        if self.current_user is None:
            print("No user is currently logged in.")
            return
        if task not in self.permissions[self.current_user]:
            print(f"User {self.current_user} does not have permission to perform task: {task}")
            return
        print(f"User {self.current_user} is performing task: {task}")
        time.sleep(random.randint(1, 5))  # Simulate task duration

    def logout(self):
        if self.current_user is None:
            print("No user is currently logged in.")
            return
        print(f"User {self.current_user} has logged out of {self.facility_name}.")
        self.current_user = None

# Example usage
if __name__ == "__main__":
    facility = FacilityAccess("Chemical/Biological Synthesis Facility")

